USE [LMS_DEV]
GO

-- Substitutes personal identifiers, contact details, addresses, and payment-account identifiers.
-- Financial amounts, ratios, rates, and workflow values are intentionally left unchanged.

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @ApplyMasking BIT = 0;
DECLARE @RowsAffected INT;

IF DB_NAME() <> N'LMS_DEV'
    THROW 51000, 'Masking stopped: this script is restricted to LMS_DEV. Update the database guard only after confirming the target is an isolated copy.', 1;

IF OBJECT_ID(N'dbo.CORE_FLEX_ALL_APPS_MASTER', N'U') IS NULL
    THROW 51001, 'Masking stopped: dbo.CORE_FLEX_ALL_APPS_MASTER does not exist in LMS_DEV.', 1;

IF @ApplyMasking = 0
BEGIN
    SELECT
        DB_NAME() AS TargetDatabase,
        COUNT_BIG(*) AS RowsToMask,
        CAST(0 AS BIT) AS ChangesApplied,
        N'Preview only. Set @ApplyMasking = 1 after confirming this is an isolated, backed-up database copy. Financial values are not modified.' AS Message
    FROM dbo.CORE_FLEX_ALL_APPS_MASTER

    RETURN
END

BEGIN TRY
    BEGIN TRANSACTION

    ;WITH RankedRows AS
    (
        SELECT
            master.*,
            ROW_NUMBER() OVER (ORDER BY master.APPLICATIONID, master.CUSTOMERID) AS MaskRow
        FROM dbo.CORE_FLEX_ALL_APPS_MASTER AS master
    ),
    RowsToMask AS
    (
        SELECT
            ranked.*,
            CHOOSE((MaskRow % 8) + 1, N'Amira', N'Noura', N'Layan', N'Sami', N'Rami', N'Talia', N'Zayn', N'Mira')
                + N' ' +
            CHOOSE(((MaskRow / 8) % 8) + 1, N'Valen', N'Marlow', N'Delan', N'Noor', N'Selim', N'Kellan', N'Faris', N'Rowan') AS FakeName1,
            CHOOSE(((MaskRow + 2) % 8) + 1, N'Amira', N'Noura', N'Layan', N'Sami', N'Rami', N'Talia', N'Zayn', N'Mira')
                + N' ' +
            CHOOSE(((MaskRow / 8 + 3) % 8) + 1, N'Valen', N'Marlow', N'Delan', N'Noor', N'Selim', N'Kellan', N'Faris', N'Rowan') AS FakeName2,
            CHOOSE(((MaskRow + 4) % 8) + 1, N'Amira', N'Noura', N'Layan', N'Sami', N'Rami', N'Talia', N'Zayn', N'Mira')
                + N' ' +
            CHOOSE(((MaskRow / 8 + 5) % 8) + 1, N'Valen', N'Marlow', N'Delan', N'Noor', N'Selim', N'Kellan', N'Faris', N'Rowan') AS FakeName3,
            CHOOSE(((MaskRow + 6) % 8) + 1, N'Amira', N'Noura', N'Layan', N'Sami', N'Rami', N'Talia', N'Zayn', N'Mira')
                + N' ' +
            CHOOSE(((MaskRow / 8 + 7) % 8) + 1, N'Valen', N'Marlow', N'Delan', N'Noor', N'Selim', N'Kellan', N'Faris', N'Rowan') AS FakeName4
        FROM RankedRows AS ranked
    )
    UPDATE RowsToMask
    SET
        CUSTOMERID = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERID))), N'') IS NULL
            THEN CUSTOMERID ELSE CONVERT(VARCHAR(20), 100000000 + (MaskRow % 800000000)) END,
        CUSTOMERID1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERID1))), N'') IS NULL
            THEN CUSTOMERID1 ELSE CONVERT(VARCHAR(20), 100000000 + (MaskRow % 800000000)) END,
        CUSTOMERID2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERID2))), N'') IS NULL
            THEN CUSTOMERID2 ELSE CONVERT(VARCHAR(20), 100000000 + ((MaskRow * 5 + 2) % 800000000)) END,
        CUSTOMERID3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERID3))), N'') IS NULL
            THEN CUSTOMERID3 ELSE CONVERT(VARCHAR(20), 100000000 + ((MaskRow * 5 + 3) % 800000000)) END,
        CUSTOMERID4 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERID4))), N'') IS NULL
            THEN CUSTOMERID4 ELSE CONVERT(VARCHAR(20), 100000000 + ((MaskRow * 5 + 4) % 800000000)) END,
        CIF = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CIF))), N'') IS NULL
            THEN CIF ELSE CONVERT(VARCHAR(20), 100000000 + (MaskRow % 800000000)) END,
        STAFF_ID = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), STAFF_ID))), N'') IS NULL
            THEN STAFF_ID ELSE CONVERT(VARCHAR(20), 100000000 + ((MaskRow * 7) % 800000000)) END,
        TRADE_LIC_NO = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), TRADE_LIC_NO))), N'') IS NULL
            THEN TRADE_LIC_NO ELSE CONVERT(VARCHAR(20), 100000000 + ((MaskRow * 11) % 800000000)) END,
        PASSPORTNUMBER = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PASSPORTNUMBER))), N'') IS NULL
            THEN PASSPORTNUMBER ELSE N'TSTP' + CONVERT(NVARCHAR(20), MaskRow) + N'01' END,
        PASSPORTNUMBER1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PASSPORTNUMBER1))), N'') IS NULL
            THEN PASSPORTNUMBER1 ELSE N'TSTP' + CONVERT(NVARCHAR(20), MaskRow) + N'01' END,
        PASSPORTNUMBER2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PASSPORTNUMBER2))), N'') IS NULL
            THEN PASSPORTNUMBER2 ELSE N'TSTP' + CONVERT(NVARCHAR(20), MaskRow) + N'02' END,
        PASSPORTNUMBER3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PASSPORTNUMBER3))), N'') IS NULL
            THEN PASSPORTNUMBER3 ELSE N'TSTP' + CONVERT(NVARCHAR(20), MaskRow) + N'03' END,
        PASSPORTNUMBER4 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PASSPORTNUMBER4))), N'') IS NULL
            THEN PASSPORTNUMBER4 ELSE N'TSTP' + CONVERT(NVARCHAR(20), MaskRow) + N'04' END,
        CUSTOMER_PASSPORTNO = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMER_PASSPORTNO))), N'') IS NULL
            THEN CUSTOMER_PASSPORTNO ELSE N'TSTP' + CONVERT(NVARCHAR(20), MaskRow) + N'01' END,
        EMIRATES_ID = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), EMIRATES_ID))), N'') IS NULL
            THEN EMIRATES_ID ELSE N'784-0000-' + RIGHT(N'000000000' + CONVERT(NVARCHAR(20), MaskRow), 9) END,
        NATIONALITY1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), NATIONALITY1))), N'') IS NULL THEN NATIONALITY1 ELSE N'ZZ' END,
        NATIONALITY2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), NATIONALITY2))), N'') IS NULL THEN NATIONALITY2 ELSE N'ZZ' END,
        NATIONALITY3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), NATIONALITY3))), N'') IS NULL THEN NATIONALITY3 ELSE N'ZZ' END,
        NATIONALITY4 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), NATIONALITY4))), N'') IS NULL THEN NATIONALITY4 ELSE N'ZZ' END,
        NATIONALITY11 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), NATIONALITY11))), N'') IS NULL THEN NATIONALITY11 ELSE N'ZZ' END,

        CUSTOMERNAME1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERNAME1))), N'') IS NULL THEN CUSTOMERNAME1 ELSE FakeName1 END,
        CUSTOMERNAME2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERNAME2))), N'') IS NULL THEN CUSTOMERNAME2 ELSE FakeName2 END,
        CUSTOMERNAME3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERNAME3))), N'') IS NULL THEN CUSTOMERNAME3 ELSE FakeName3 END,
        CUSTOMERNAME4 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERNAME4))), N'') IS NULL THEN CUSTOMERNAME4 ELSE FakeName4 END,
        CUSTOMERNAME11 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERNAME11))), N'') IS NULL THEN CUSTOMERNAME11 ELSE FakeName1 END,
        CUSTOMERNAME21 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERNAME21))), N'') IS NULL THEN CUSTOMERNAME21 ELSE FakeName2 END,
        CUSTOMERNAME31 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMERNAME31))), N'') IS NULL THEN CUSTOMERNAME31 ELSE FakeName3 END,
        CUSTOMER_NAME1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CUSTOMER_NAME1))), N'') IS NULL THEN CUSTOMER_NAME1 ELSE FakeName1 END,
        Co_Applicant_1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), Co_Applicant_1))), N'') IS NULL THEN Co_Applicant_1 ELSE FakeName2 END,
        Co_Applicant_2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), Co_Applicant_2))), N'') IS NULL THEN Co_Applicant_2 ELSE FakeName3 END,
        Co_Applicant_3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), Co_Applicant_3))), N'') IS NULL THEN Co_Applicant_3 ELSE FakeName4 END,
        DATEOFBIRTH1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), DATEOFBIRTH1))), N'') IS NULL THEN DATEOFBIRTH1 ELSE CONVERT(CHAR(10), DATEADD(DAY, (MaskRow * 37) % 12000, CONVERT(DATE, '19700101')), 23) END,
        DATEOFBIRTH2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), DATEOFBIRTH2))), N'') IS NULL THEN DATEOFBIRTH2 ELSE CONVERT(CHAR(10), DATEADD(DAY, (MaskRow * 37 + 211) % 12000, CONVERT(DATE, '19700101')), 23) END,
        DATEOFBIRTH3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), DATEOFBIRTH3))), N'') IS NULL THEN DATEOFBIRTH3 ELSE CONVERT(CHAR(10), DATEADD(DAY, (MaskRow * 37 + 422) % 12000, CONVERT(DATE, '19700101')), 23) END,
        DATEOFBIRTH4 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), DATEOFBIRTH4))), N'') IS NULL THEN DATEOFBIRTH4 ELSE CONVERT(CHAR(10), DATEADD(DAY, (MaskRow * 37 + 633) % 12000, CONVERT(DATE, '19700101')), 23) END,
        DATEOFBIRTH11 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), DATEOFBIRTH11))), N'') IS NULL THEN DATEOFBIRTH11 ELSE CONVERT(CHAR(10), DATEADD(DAY, (MaskRow * 37) % 12000, CONVERT(DATE, '19700101')), 23) END,

        PERSONAL_EMAIL = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PERSONAL_EMAIL))), N'') IS NULL THEN PERSONAL_EMAIL ELSE N'user' + CONVERT(NVARCHAR(20), MaskRow) + N'@example.invalid' END,
        PERSONAL_EMAIL1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PERSONAL_EMAIL1))), N'') IS NULL THEN PERSONAL_EMAIL1 ELSE N'user' + CONVERT(NVARCHAR(20), MaskRow) + N'@example.invalid' END,
        PERSONAL_EMAIL2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PERSONAL_EMAIL2))), N'') IS NULL THEN PERSONAL_EMAIL2 ELSE N'user' + CONVERT(NVARCHAR(20), MaskRow) + N'@example.invalid' END,
        OFFICE_EMAIL = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), OFFICE_EMAIL))), N'') IS NULL THEN OFFICE_EMAIL ELSE N'office' + CONVERT(NVARCHAR(20), MaskRow) + N'@example.invalid' END,
        OFFICE_EMAIL1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), OFFICE_EMAIL1))), N'') IS NULL THEN OFFICE_EMAIL1 ELSE N'office' + CONVERT(NVARCHAR(20), MaskRow) + N'@example.invalid' END,
        OFFICE_EMAIL2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), OFFICE_EMAIL2))), N'') IS NULL THEN OFFICE_EMAIL2 ELSE N'office' + CONVERT(NVARCHAR(20), MaskRow) + N'@example.invalid' END,
        MOBILECODE = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MOBILECODE))), N'') IS NULL THEN MOBILECODE ELSE N'000' END,
        MOBILECODE1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MOBILECODE1))), N'') IS NULL THEN MOBILECODE1 ELSE N'000' END,
        MOBILENUMBER = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MOBILENUMBER))), N'') IS NULL THEN MOBILENUMBER ELSE N'000' + RIGHT(N'0000000' + CONVERT(NVARCHAR(20), MaskRow), 7) END,
        MOBILENUMBER1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MOBILENUMBER1))), N'') IS NULL THEN MOBILENUMBER1 ELSE N'000' + RIGHT(N'0000000' + CONVERT(NVARCHAR(20), MaskRow), 7) END,
        MOBILENUMBER2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MOBILENUMBER2))), N'') IS NULL THEN MOBILENUMBER2 ELSE N'000' + RIGHT(N'0000000' + CONVERT(NVARCHAR(20), MaskRow), 7) END,
        RESI_TEL_CODE = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_TEL_CODE))), N'') IS NULL THEN RESI_TEL_CODE ELSE N'000' END,
        RESI_TEL_NUM = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_TEL_NUM))), N'') IS NULL THEN RESI_TEL_NUM ELSE N'000' + RIGHT(N'0000000' + CONVERT(NVARCHAR(20), MaskRow + 1), 7) END,
        RESI_TEL_CODE1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_TEL_CODE1))), N'') IS NULL THEN RESI_TEL_CODE1 ELSE N'000' END,
        RESI_TEL_NUM1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_TEL_NUM1))), N'') IS NULL THEN RESI_TEL_NUM1 ELSE N'000' + RIGHT(N'0000000' + CONVERT(NVARCHAR(20), MaskRow + 1), 7) END,
        OFFICE_TEL_CODE = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), OFFICE_TEL_CODE))), N'') IS NULL THEN OFFICE_TEL_CODE ELSE N'000' END,
        OFFICE_TEL_NUM = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), OFFICE_TEL_NUM))), N'') IS NULL THEN OFFICE_TEL_NUM ELSE N'000' + RIGHT(N'0000000' + CONVERT(NVARCHAR(20), MaskRow + 2), 7) END,
        HC_TEL_CODE = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), HC_TEL_CODE))), N'') IS NULL THEN HC_TEL_CODE ELSE N'000' END,
        HC_TEL_NUM = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), HC_TEL_NUM))), N'') IS NULL THEN HC_TEL_NUM ELSE N'000' + RIGHT(N'0000000' + CONVERT(NVARCHAR(20), MaskRow + 3), 7) END,
        H_Country_Phone = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), H_Country_Phone))), N'') IS NULL THEN H_Country_Phone ELSE N'000' END,
        FAX_CODE = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), FAX_CODE))), N'') IS NULL THEN FAX_CODE ELSE N'000' END,
        FAX_NUMBER = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), FAX_NUMBER))), N'') IS NULL THEN FAX_NUMBER ELSE N'000' + RIGHT(N'0000000' + CONVERT(NVARCHAR(20), MaskRow + 4), 7) END,
        ALTERNATE_CONTACT_CODE = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), ALTERNATE_CONTACT_CODE))), N'') IS NULL THEN ALTERNATE_CONTACT_CODE ELSE N'000' END,
        ALTERNATE_CONTACT = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), ALTERNATE_CONTACT))), N'') IS NULL THEN ALTERNATE_CONTACT ELSE N'000' + RIGHT(N'0000000' + CONVERT(NVARCHAR(20), MaskRow + 5), 7) END,
        ALTERNATE_CONT_NO = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), ALTERNATE_CONT_NO))), N'') IS NULL THEN ALTERNATE_CONT_NO ELSE N'000' + RIGHT(N'0000000' + CONVERT(NVARCHAR(20), MaskRow + 5), 7) END,

        MAILING_POBOX = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MAILING_POBOX))), N'') IS NULL THEN MAILING_POBOX ELSE N'TEST-' + CONVERT(NVARCHAR(20), MaskRow) END,
        MAILING_POBOX1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MAILING_POBOX1))), N'') IS NULL THEN MAILING_POBOX1 ELSE N'TEST-' + CONVERT(NVARCHAR(20), MaskRow) END,
        MAILING_CITY = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MAILING_CITY))), N'') IS NULL THEN MAILING_CITY ELSE N'Test City ' + CONVERT(NVARCHAR(20), MaskRow) END,
        MAILING_COUNTRY = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MAILING_COUNTRY))), N'') IS NULL THEN MAILING_COUNTRY ELSE N'Testland' END,
        MAILING_COUNTRY1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MAILING_COUNTRY1))), N'') IS NULL THEN MAILING_COUNTRY1 ELSE N'Testland' END,
        RESI_ADDRESS1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_ADDRESS1))), N'') IS NULL THEN RESI_ADDRESS1 ELSE N'Synthetic residential address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        RESI_ADDRESS2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_ADDRESS2))), N'') IS NULL THEN RESI_ADDRESS2 ELSE N'Synthetic residential address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        RESI_ADDRESS3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_ADDRESS3))), N'') IS NULL THEN RESI_ADDRESS3 ELSE N'Synthetic residential address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        RESI_ADDRESS4 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_ADDRESS4))), N'') IS NULL THEN RESI_ADDRESS4 ELSE N'Synthetic residential address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        RESI_ADDRESS11 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_ADDRESS11))), N'') IS NULL THEN RESI_ADDRESS11 ELSE N'Synthetic residential address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        RESI_ADDRESS21 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_ADDRESS21))), N'') IS NULL THEN RESI_ADDRESS21 ELSE N'Synthetic residential address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        RESI_ADDRESS31 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), RESI_ADDRESS31))), N'') IS NULL THEN RESI_ADDRESS31 ELSE N'Synthetic residential address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        HOMECOUNTRY_ADD1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), HOMECOUNTRY_ADD1))), N'') IS NULL THEN HOMECOUNTRY_ADD1 ELSE N'Synthetic home address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        HOMECOUNTRY_ADD2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), HOMECOUNTRY_ADD2))), N'') IS NULL THEN HOMECOUNTRY_ADD2 ELSE N'Synthetic home address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        HOMECOUNTRY_ADD3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), HOMECOUNTRY_ADD3))), N'') IS NULL THEN HOMECOUNTRY_ADD3 ELSE N'Synthetic home address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        OFFICE_ADDRESS1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), OFFICE_ADDRESS1))), N'') IS NULL THEN OFFICE_ADDRESS1 ELSE N'Synthetic office address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        OFFICE_ADDRESS2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), OFFICE_ADDRESS2))), N'') IS NULL THEN OFFICE_ADDRESS2 ELSE N'Synthetic office address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        OFFICE_ADDRESS3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), OFFICE_ADDRESS3))), N'') IS NULL THEN OFFICE_ADDRESS3 ELSE N'Synthetic office address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        Property_Address = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), Property_Address))), N'') IS NULL THEN Property_Address ELSE N'Synthetic property address ' + CONVERT(NVARCHAR(20), MaskRow) END,
        PROPERTYDETAILS = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PROPERTYDETAILS))), N'') IS NULL THEN PROPERTYDETAILS ELSE N'Synthetic property details ' + CONVERT(NVARCHAR(20), MaskRow) END,
        Add_Of_Employer = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), Add_Of_Employer))), N'') IS NULL THEN Add_Of_Employer ELSE N'Synthetic employer address ' + CONVERT(NVARCHAR(20), MaskRow) END,

        CURRENTEMPLOYER1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CURRENTEMPLOYER1))), N'') IS NULL THEN CURRENTEMPLOYER1 ELSE N'Northstar Services' END,
        CURRENTEMPLOYER2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CURRENTEMPLOYER2))), N'') IS NULL THEN CURRENTEMPLOYER2 ELSE N'Bluehaven Trading' END,
        CURRENTEMPLOYER3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CURRENTEMPLOYER3))), N'') IS NULL THEN CURRENTEMPLOYER3 ELSE N'Cedar Bay Logistics' END,
        CURRENTEMPLOYER4 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), CURRENTEMPLOYER4))), N'') IS NULL THEN CURRENTEMPLOYER4 ELSE N'Summit Grove Consulting' END,
        Name_Of_Employer = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), Name_Of_Employer))), N'') IS NULL THEN Name_Of_Employer ELSE N'Northstar Services' END,
        DESIGNATION1 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), DESIGNATION1))), N'') IS NULL THEN DESIGNATION1 ELSE N'Operations Analyst' END,
        DESIGNATION2 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), DESIGNATION2))), N'') IS NULL THEN DESIGNATION2 ELSE N'Project Coordinator' END,
        DESIGNATION3 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), DESIGNATION3))), N'') IS NULL THEN DESIGNATION3 ELSE N'Service Associate' END,
        DESIGNATION4 = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), DESIGNATION4))), N'') IS NULL THEN DESIGNATION4 ELSE N'Business Specialist' END,
        Designation = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), Designation))), N'') IS NULL THEN Designation ELSE N'Operations Analyst' END,
        SALES_OFFICER = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), SALES_OFFICER))), N'') IS NULL THEN SALES_OFFICER ELSE FakeName1 END,
        MA_NAME = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), MA_NAME))), N'') IS NULL THEN MA_NAME ELSE FakeName2 END,
        SELLERNAME = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), SELLERNAME))), N'') IS NULL THEN SELLERNAME ELSE FakeName3 END,

        Repayment_AC = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), Repayment_AC))), N'') IS NULL THEN Repayment_AC ELSE N'TESTAC' + CONVERT(NVARCHAR(20), MaskRow) END,
        DR_SETL_AC = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), DR_SETL_AC))), N'') IS NULL THEN DR_SETL_AC ELSE N'TESTAC' + CONVERT(NVARCHAR(20), MaskRow) END,
        Repayment_Bank = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), Repayment_Bank))), N'') IS NULL THEN Repayment_Bank ELSE N'Synthetic Bank' END,
        PREAPPROVALNO = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PREAPPROVALNO))), N'') IS NULL THEN PREAPPROVALNO ELSE N'TEST-APP-' + CONVERT(NVARCHAR(20), MaskRow) END,
        PDC_NO = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), PDC_NO))), N'') IS NULL THEN PDC_NO ELSE CONVERT(VARCHAR(20), 100000000 + ((MaskRow * 13) % 800000000)) END,
        contract_ref_no = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), contract_ref_no))), N'') IS NULL THEN contract_ref_no ELSE N'TEST-CONTRACT-' + CONVERT(NVARCHAR(20), MaskRow) END,
        LAND_REG = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), LAND_REG))), N'') IS NULL THEN LAND_REG ELSE N'TEST-LAND-' + CONVERT(NVARCHAR(20), MaskRow) END,
        Land_Regestration = CASE WHEN NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(4000), Land_Regestration))), N'') IS NULL THEN Land_Regestration ELSE N'TEST-LAND-' + CONVERT(NVARCHAR(20), MaskRow) END

    SET @RowsAffected = @@ROWCOUNT

    COMMIT TRANSACTION

    SELECT
        DB_NAME() AS TargetDatabase,
        @RowsAffected AS RowsUpdated,
        CAST(1 AS BIT) AS ChangesApplied
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH
GO
